export function inferCategory(text) {
 if(/설치|가입/.test(text)) return 'AI 기초';
 const patterns=[['AI 공부·심화',/rag|llm|파인튜닝|머신러닝|심화|에이전트|agent|원리|개념|공부|학습|논문/i],['AI 업무 활용',/업무|자동화|엑셀|보고서|메일|스킬|반복|문서|회의록/],['AI 콘텐츠',/콘텐츠|이미지|영상|디자인|유튜브|브랜드|인스타/],['AI 창업',/창업|사업|mvp|고객|검증|기획안/i],['AI 제작',/서비스|웹|앱|사이트|프로젝트|cursor|replit|v0|코딩|개발|배포/i],['AI 기초',/처음|설치|가입|기초|시작|질문|chatgpt/i]];
 return patterns.find(([,re])=>re.test(text))?.[0] || null;
}
export function rankMentors(category,level) {
 return mentors.map(m=>({...m,score:(m.category===category?10:0)+(m.level.includes(level)?3:0)+(m.category==='AI 기초'&&level==='처음 시작해요'?2:0)})).sort((a,b)=>b.score-a.score).slice(0,3);
}
